        return res;
    }
    catch (Exception ex2)
    {
        try
        {
            var res = decimal.Parse(value);
            return res;
        }
        catch (Exception ex3)
        {

            try
            {
                var res = DateTime.Parse(value);
                return res;
            }
            catch (Exception ex4)
            {
                try
                {
                    var res = bool.Parse(value);
                    return res;

                }
                catch (Exception ex5)
                {
                    return value;
                }
            }

        }
    }

