    {
        List<Teams> teams = _context.Teams.Where(a => a.GameId == gameId.ToString()).ToList();
        foreach(Teams team in teams)
        {
            List<TeamToUsers> t2users = _context.TeamToUsers.Where(a => a.TeamId == team.Id.ToString()).ToList();
            foreach(TeamToUsers t2user in t2users)
            {
                Users user = _context.Users.Where(a => a.Id.ToString() == t2user.UserId).FirstOrDefault();
                Player player = new Player();
                player.Name = user.Fullname;
                player.UserId = user.Userid;
                player.icon = t2user.Icon;
                player.color = t2user.Color;
                player.IsWinner = false;
                player.GameId = gameId.ToString();
                player.TeamId = team.Id.ToString();
                if (myGame.Status == "Done" && myGame.ActiveTeam == team.Id.ToString())
                {
                    player.IsWinner = true;
                }
                player.Status = "waiting";
                if(myGame.ActiveTeam== team.Id.ToString() && team.Activeuser==user.Id.ToString())
                {

                    player.Status = t2user.Status;
                }


                List<ActionWithStates> actionWithStates = new List<ActionWithStates>();

                List<Cards> gameCards = _context.Cards.Where(a => a.Language == language).OrderBy(a => a.OrderNum).ToList();
                int placement = 0;
                int.TryParse(t2user.ActivePlacement.ToString(), out placement);

                Cards activeCard = gameCards[placement];
                player.ActiveCard = activeCard.Id.ToString();
                List<Actions> actions = _context.Actions.Where(a => a.ParentId == activeCard.Id.ToString()).ToList();
                List<StateSummary> myStates = GameHelpers.CalculateStats(myGame, team, _context);
                bool DidIWin = GameHelpers.TestIfGameFinishReached(myGame, myStates, _context);
                if (DidIWin)
                {
                    myGame.Status = "Won";
                    myGame.ActiveTeam = team.Id.ToString();
                    _context.SaveChanges();
                    player.Status = "Won";
                }
                else
                {
                    if(player.Status =="Choose Action")
                    { 
                    foreach (Actions action in actions)
                    {
                        GameHelpers.AddActionExt(actionWithStates, action, _context, myGame, myTeam, myStates);
                    }
                    }
                }
                player.actionWithStates = actionWithStates;
                player.States = myStates;
                player.numbers = new Numbers { firstNum = t2user.FirstNum, secondNum = t2user.LastNum };

                player.moves = _context.TeamHistoryMoves.Where(a => a.GameId == gameId.ToString() && a.Teamid == team.Id.ToString()).OrderBy(a=>a.ActionNum).ToList();
                result.Add(player);
